"""Generate the non-AI generic action list for victory path UI controls."""

import argparse
import sys
from pathlib import Path

if hasattr(sys.stdout, "reconfigure"):
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")

import yaml

REPO_ROOT = Path(__file__).resolve().parents[4]
DATA_FILE = REPO_ROOT / "data" / "victory_paths.yaml"
OUT_FILE = (
    REPO_ROOT
    / "src"
    / "in_game"
    / "common"
    / "generic_action_ai_lists"
    / "towards_victory_reward_actions_list.txt"
)

HEADER = """\
# @Generated by scripts/in_game/common/generic_action_ai_lists/gen_towards_victory_reward_actions_list.py
#   Data:    data/victory_paths.yaml
#   Regen:   conda run --no-capture-output -n eu5 python scripts/in_game/common/generic_action_ai_lists/gen_towards_victory_reward_actions_list.py
# Do not edit directly - modify the data file and re-run the generator.
"""


def action_ids(data: dict) -> list[str]:
    paths = sorted(data["paths"], key=lambda path: int(path["gui"]["order"]))
    ids: list[str] = []
    for path in paths:
        ids.append(f"tv_victory_select_path_{path['id']}")
    for path in paths:
        pid = path["id"]
        for milestone in path["milestones"]:
            n = int(milestone["n"])
            for choice in range(1, 4):
                ids.append(f"tv_victory_select_{pid}_m{n}_reward_{choice}")
    return ids


def generate(data: dict) -> str:
    lines = [HEADER.rstrip(), "", "towards_victory_reward_actions_list = {"]
    lines.append("\tpotential = { always = no }")
    lines.append("\tactions = {")
    for action_id in action_ids(data):
        lines.append(f"\t\t{action_id}")
    lines.append("\t}")
    lines.append("}")
    lines.append("")
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--dry", action="store_true", help="Print to stdout instead of writing")
    args = parser.parse_args()

    with DATA_FILE.open(encoding="utf-8-sig") as file:
        data = yaml.safe_load(file)

    content = generate(data)
    if args.dry:
        print(content)
    else:
        OUT_FILE.parent.mkdir(parents=True, exist_ok=True)
        OUT_FILE.write_text(content, encoding="utf-8-sig")
        print(f"Written: {OUT_FILE.relative_to(REPO_ROOT)}")


if __name__ == "__main__":
    main()
